mapper.select:
SELECT * FROM item

     AND status = #{q.getStatus()} 
     AND seller_id = #{q.getSellerId()} 
     AND category = #{q.getCategory()} 
     AND `condition` = #{q.getCondition()} 

        AND (trade_method = #{q.getTradeMethod()} OR trade_method = 'BOTH')

     AND price >= #{q.getMinPrice()} 
     AND price <= #{q.getMaxPrice()} 

        AND (title LIKE CONCAT('%', #{q.getKeyword()}, '%')
          OR description LIKE CONCAT('%', #{q.getKeyword()}, '%'))



      ORDER BY price ASC,  id DESC 
     ORDER BY price DESC, id DESC 
                                      ORDER BY created_at DESC, id DESC
